# Living birds, first batch: every penguin and every ratite species. Birds are too species-rich
# for every genus, so other families get only their best-known members (in later batches).
# Ranges show where each species breeds or lives year-round, roughly; seabirds range much wider at
# sea. IUCN statuses are given only where well established.


def C(*names, **clip):
    return {'countries': list(names), **clip}


def part(country, lon0, lat0, lon1, lat1):
    return {'country': country, 'bbox': [lon0, lat0, lon1, lat1]}


def sea(lon0, lat0, lon1, lat1):
    return {'sea': [lon0, lat0, lon1, lat1]}


